const TZ = 'Africa/Lagos';
const s = (v) => String(v === null || v === undefined ? '' : v).trim();
const todayStr = () => new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(new Date());
const nowIso = () => new Date(Date.now() + 3600000).toISOString().replace(/\.\d{3}Z$/, '+01:00');
const uid = (p) => p + '-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2, 7).toUpperCase();
const isEmail = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s(e));
const isDate = (d) => /^\d{4}-\d{2}-\d{2}$/.test(d) && !isNaN(Date.parse(d + 'T00:00:00Z'));
const daysBetween = (a, b) => Math.floor((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
const mkLog = (o) => Object.assign({ event_id: uid('EVT'), customer_id: '', email: '', event_type: '', campaign_id: '', email_sequence: '', message_id: '', booking_id: '', timestamp: nowIso(), status: '', error: '', metadata: '' }, o);
const mkErr = (o) => Object.assign({ error_id: uid('ERR'), workflow: '', customer_id: '', node: '', error_type: 'UNKNOWN', message: '', timestamp: nowIso(), retry_count: 0, resolved: 'FALSE', execution_id: String($execution.id) }, o);

const S = $('Get Settings').first().json.settings;
const camp = s(S.campaign_id);
const log = $input.all().map(i => i.json).filter(l => l.event_id && s(l.campaign_id) === camp);
const uniq = (fn) => new Set(log.filter(fn).map(l => s(l.customer_id)).filter(Boolean)).size;
const sent = log.filter(l => l.event_type === 'EMAIL_SENT');
const contacted = new Set(sent.filter(l => s(l.email_sequence) === 'INITIAL').map(l => s(l.customer_id))).size;
const followups = sent.filter(l => s(l.email_sequence) !== 'INITIAL').length;
const eligible = uniq(l => l.event_type === 'ELIGIBLE_MARKED');
const delivered = uniq(l => l.event_type === 'EMAIL_DELIVERED');
const clicked = uniq(l => l.event_type === 'EMAIL_CLICKED');
const cancelled = uniq(l => l.event_type === 'BOOKING_CANCELLED');
const unsubscribed = uniq(l => l.event_type === 'UNSUBSCRIBED');
const complained = uniq(l => l.event_type === 'EMAIL_COMPLAINED');
const bounced = uniq(l => l.event_type === 'EMAIL_BOUNCED');
const unmatched = log.filter(l => l.event_type === 'BOOKING_UNMATCHED').length;
const state = {};
for (const l of log) {
  const k = s(l.customer_id) + '|' + s(l.email_sequence);
  if (l.event_type === 'EMAIL_FAILED') state[k] = 'F';
  else if (l.event_type === 'EMAIL_SENT') state[k] = 'S';
}
const failed = new Set(Object.keys(state).filter(k => state[k] === 'F').map(k => k.split('|')[0])).size;
const firstSent = {};
sent.forEach(l => { const c = s(l.customer_id); const t = Date.parse(s(l.timestamp)); if (!isNaN(t) && (firstSent[c] === undefined || t < firstSent[c])) firstSent[c] = t; });
const booked = new Set(log.filter(l => l.event_type === 'BOOKING_CREATED' && firstSent[s(l.customer_id)] !== undefined && Date.parse(s(l.timestamp)) > firstSent[s(l.customer_id)]).map(l => s(l.customer_id))).size;
const denom = delivered > 0 ? delivered : contacted;
const rate = denom ? (booked / denom * 100).toFixed(1) + '%' : '0.0%';
const today = todayStr();
const lines = [
  'CUSTOMER REACTIVATION REPORT',
  'Campaign: ' + camp + '   Date: ' + today, '',
  'Customers eligible: ' + eligible,
  'Customers contacted: ' + contacted,
  'Follow-up emails sent: ' + followups,
  'Bookings from this campaign: ' + booked,
  'Booking rate: ' + rate,
  'Cancelled bookings: ' + cancelled,
  'Unsubscribed: ' + unsubscribed,
  'Emails that failed to send: ' + failed
];
if (delivered > 0) lines.push('Delivered: ' + delivered + '   Bounced: ' + bounced + '   Complaints: ' + complained);
if (unmatched > 0) lines.push('', 'Bookings that could not be matched to a customer: ' + unmatched + ' (please check)');
if (s(S.report_sheet_url)) lines.push('', 'Detailed results: ' + s(S.report_sheet_url));
const resultsRow = { campaign_id: camp, date: today, eligible, contacted, followups_sent: followups, delivered, clicked, booked, cancelled, unsubscribed, complained, bounced, failed, revenue: 0 };
return [{ json: { resultsRow, subject: 'Weekly customer reactivation report - ' + s(S.business_name), text: lines.join('\n'), to: s(S.owner_email), camp } }];

